using SQLite;

namespace Draftmaster.Data
{
    public enum RaceStatus
    {
        Finished = 0,
        DNF = 1,   // did not finish (crash/mechanical)
        DNS = 2,   // did not start
        DSQ = 3    // disqualified
    }

    // One driver's outcome in one race. Generated by the player's race or the background sim.
    [Table("Results")]
    public class Result
    {
        [PrimaryKey, AutoIncrement]
        public int Id { get; set; }

        [Indexed] public int RaceId { get; set; }
        // Denormalised for cheap querying without a Race join.
        [Indexed] public int SeriesId { get; set; }
        [Indexed] public int Season { get; set; }
        public int Round { get; set; }

        [Indexed] public int DriverId { get; set; }
        public int TeamId { get; set; }

        public int StartPosition { get; set; }
        public int FinishPosition { get; set; }
        public int Points { get; set; }
        public int LapsLed { get; set; }
        public bool FastestLap { get; set; }
        public RaceStatus Status { get; set; }
        public string DnfReason { get; set; }
        public bool IsPlayer { get; set; }
    }
}
